import React, { useEffect, useState } from 'react';
import api from '../services/api';
import ExpenseChart from '../components/ExpenseChart';
import ExpenseForm from '../components/ExpenseForm';
import ExpenseList from '../components/ExpenseList';

export default function Dashboard() {
  const [summary, setSummary] = useState({ total: 0, breakdown: [] });
  const [expenses, setExpenses] = useState([]);

  const fetchData = async () => {
    try {
      const [summaryRes, expensesRes] = await Promise.all([
        api.get('/reports/summary'),
        api.get('/expenses')
      ]);
      setSummary(summaryRes.data);
      setExpenses(expensesRes.data);
    } catch (err) {
      console.error(err);
    }
  };

  useEffect(() => {
    fetchData();
  }, []);

  return (
    <div className="p-8">
      <div className="flex justify-between items-center mb-8">
        <h1 className="text-3xl font-bold">SpendWise Dashboard</h1>
        <button onClick={() => { localStorage.removeItem('token'); window.location.reload(); }} className="bg-red-500 text-white px-4 py-2 rounded">Logout</button>
      </div>

      <div className="grid grid-cols-1 md:grid-cols-2 gap-8 mb-8">
        <div className="bg-white p-6 rounded shadow">
          <h2 className="text-xl font-semibold mb-4">Monthly Summary</h2>
          <p className="text-4xl font-bold text-blue-600">${summary.total.toFixed(2)}</p>
          <div className="h-64">
            <ExpenseChart data={summary.breakdown} />
          </div>
        </div>
        <div className="bg-white p-6 rounded shadow">
          <h2 className="text-xl font-semibold mb-4">Add New Expense</h2>
          <ExpenseForm onAdd={fetchData} />
        </div>
      </div>

      <div className="bg-white p-6 rounded shadow">
        <h2 className="text-xl font-semibold mb-4">Recent Expenses</h2>
        <ExpenseList expenses={expenses} onDelete={fetchData} />
      </div>
    </div>
  );
}

import React from 'react';
import { PieChart, Pie, Cell, ResponsiveContainer, Tooltip, Legend } from 'recharts';

const COLORS = ['#0088FE', '#00C49F', '#FFBB28', '#FF8042', '#8884d8'];

export default function ExpenseChart({ data }) {
  return (
    <ResponsiveContainer width="100%" height="100%">
      <PieChart>
        <Pie
          data={data}
          cx="50%"
          cy="50%"
          labelLine={false}
          outerRadius={80}
          fill="#8884d8"
          dataKey="amount"
          nameKey="category"
        >
          {data.map((entry, index) => (
            <Cell key={`cell-${index}`} fill={COLORS[index % COLORS.length]} />
          ))}
        </Pie>
        <Tooltip />
        <Legend />
      </PieChart>
    </ResponsiveContainer>
  );
}

import React, { useState } from 'react';
import api from '../services/api';

export default function ExpenseForm({ onAdd }) {
  const [amount, setAmount] = useState('');
  const [categoryId, setCategoryId] = useState(1);
  const [description, setDescription] = useState('');
  const [date, setDate] = useState(new Date().toISOString().split('T')[0]);

  const handleSubmit = async (e) => {
    e.preventDefault();
    try {
      await api.post('/expenses', {
        amount: parseFloat(amount),
        category_id: parseInt(categoryId),
        description,
        transaction_date: date
      });
      setAmount('');
      setDescription('');
      onAdd();
    } catch (err) {
      alert('Failed to add expense');
    }
  };

  return (
    <form onSubmit={handleSubmit} className="space-y-4">
      <input type="number" step="0.01" placeholder="Amount" className="w-full p-2 border rounded" value={amount} onChange={e => setAmount(e.target.value)} required />
      <select className="w-full p-2 border rounded" value={categoryId} onChange={e => setCategoryId(e.target.value)}>
        <option value="1">Food</option>
        <option value="2">Transport</option>
        <option value="3">Rent</option>
        <option value="4">Utilities</option>
        <option value="5">Entertainment</option>
      </select>
      <input type="text" placeholder="Description" className="w-full p-2 border rounded" value={description} onChange={e => setDescription(e.target.value)} />
      <input type="date" className="w-full p-2 border rounded" value={date} onChange={e => setDate(e.target.value)} required />
      <button type="submit" className="w-full bg-blue-600 text-white p-2 rounded">Add Expense</button>
    </form>
  );
}

import React from 'react';
import api from '../services/api';

export default function ExpenseList({ expenses, onDelete }) {
  const handleDelete = async (id) => {
    if (window.confirm('Are you sure?')) {
      await api.delete(`/expenses/${id}`);
      onDelete();
    }
  };

  return (
    <div className="overflow-x-auto">
      <table className="w-full text-left">
        <thead>
          <tr className="border-b">
            <th className="py-2">Date</th>
            <th className="py-2">Description</th>
            <th className="py-2">Amount</th>
            <th className="py-2">Action</th>
          </tr>
        </thead>
        <tbody>
          {expenses.map(exp => (
            <tr key={exp.id} className="border-b">
              <td className="py-2">{exp.transaction_date}</td>
              <td className="py-2">{exp.description}</td>
              <td className="py-2 font-semibold">${exp.amount.toFixed(2)}</td>
              <td className="py-2">
                <button onClick={() => handleDelete(exp.id)} className="text-red-500">Delete</button>
              </td>
            </tr>
          ))}
        </tbody>
      </table>
    </div>
  );
}
